function parsePagination(params) {
  function read(key, fallback, max) {
    const raw = params.get(key);
    if (raw === null) return fallback;
    if (!/^[0-9]+$/.test(raw)) throw new TypeError(`Invalid ${key}`);
    const value = Number(raw);
    if (!Number.isSafeInteger(value) || value < 1 || value > max) throw new RangeError(`Invalid ${key}`);
    return value;
  }
  const page = read('page', 1, 1000000);
  const limit = read('limit', 20, 100);
  return { page, limit, offset: (page - 1) * limit };
}

