import { createServer } from 'node:http';
const server = createServer((req, res) => {
  const path = new URL(req.url, 'http://localhost').pathname;
  res.setHeader('Content-Type', 'application/json; charset=utf-8');
  if (path !== '/health') { res.writeHead(404); res.end(JSON.stringify({ error: 'Not found' })); return; }
  if (req.method !== 'GET') { res.writeHead(405, { Allow: 'GET' }); res.end(JSON.stringify({ error: 'Method not allowed' })); return; }
  res.writeHead(200); res.end(JSON.stringify({ status: 'ok' }));
});
server.listen(8123, '127.0.0.1');
